head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;

//상장형 수익증권 제출인정보조회
scwin.vScrenID = "ULDSTF32005.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCodes = function() {
    var url = "/PFInfo.do?method=listPFPersonInCharge&ISUR_CD=";
    dts_WRNT_ISUR_CD.DataID = encodeURI(url);
    dts_WRNT_ISUR_CD.Reset();
};
scwin.fn_Search = function() {
    // 콤보박스 선택값
    var vSelValue = $c.cp.valueOfIndex(cmb_WRNT_ISUR_CD, "ISUR_CD", cmb_WRNT_ISUR_CD.getSelectedIndex());
    if (vSelValue.indexOf("null") > -1) {
        vSelValue = "";
    }
    var url = "/PFInfo.do?method=listPFPersonInCharge&ISUR_CD=" + vSelValue;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    if (dts_List.getTotalRow() > 0) {
        scwin.fn_readELWPersonInCharge(grd_List, 1, "ISUR_CD");
    } else {
        $c.stf.setObjectValue(txb_Corp_COM_NM, '');
        dts_Chrg1_Info.removeAll();
        dts_Chrg2_Info.removeAll();
        dts_Chrg3_Info.removeAll();
        dts_Chrg4_Info.removeAll();
        dts_Chrg5_Info.removeAll();
        dts_Chrg6_Info.removeAll();
    }
};
scwin.fn_readELWPersonInCharge = function(GridID, row, colid) {
    if (row < 1) return;
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    $c.stf.setObjectValue(txb_Corp_COM_NM, objDataID.getCellData(row, "COM_NM"));
    var url = "";
    // 공시책임자(PF(상장형 수익증권) 운용사)
    url = "/PFInfo.do?method=readPFPersonInCharge&Flag=1&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD_1");
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Chrg1_Info.DataID = encodeURI(url);
    dts_Chrg1_Info.Reset();

    // 공시담당자1(PF(상장형 수익증권) 운용사)
    url = "/PFInfo.do?method=readPFPersonInCharge&Flag=2&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD_2");
    dts_Chrg2_Info.DataID = encodeURI(url);
    dts_Chrg2_Info.Reset();

    // 공시담당자2(PF(상장형 수익증권) 운용사)
    url = "/PFInfo.do?method=readPFPersonInCharge&Flag=3&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD_3");
    dts_Chrg3_Info.DataID = encodeURI(url);
    dts_Chrg3_Info.Reset();

    // 공시책임자(PF(상장형 수익증권) 사무관리회사)
    url = "/PFInfo.do?method=readPFPersonInCharge&Flag=4&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD_4");
    dts_Chrg4_Info.DataID = encodeURI(url);
    dts_Chrg4_Info.Reset();

    // 공시담당자1(PF(상장형 수익증권) 사무관리회사)
    url = "/PFInfo.do?method=readPFPersonInCharge&Flag=5&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD_5");
    dts_Chrg5_Info.DataID = encodeURI(url);
    dts_Chrg5_Info.Reset();

    // 공시담당자2(PF(상장형 수익증권) 사무관리회사)
    url = "/PFInfo.do?method=readPFPersonInCharge&Flag=6&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD_6");
    dts_Chrg6_Info.DataID = encodeURI(url);
    dts_Chrg6_Info.Reset();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.img_toExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_List, "상장형 수익증권 제출인정보", "", "2");
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_readELWPersonInCharge(grd_List, row, colid);
};
scwin.dts_WRNT_ISUR_CD_OnLoadCompleted = function(rowcount) {
    //alert('dts_WRNT_ISUR_CD.OnLoadCompleted('+rowcount+')');
    dts_WRNT_ISUR_CD.insertRow();
    dts_WRNT_ISUR_CD.setCellData(rowcount + 1, "COM_NM", "전체");
    dts_WRNT_ISUR_CD.setCellData(rowcount + 1, "ISUR_CD", "");
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.gform_onload = function() {
    //fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCodes();
    scwin.fn_Search();
};
